//! Actions-only system-control and ordinary messages share original receive
//! ordering atomically. Relation timestamps never substitute for IM indices.
use super::*;
use n::{rpc_im::{ImQuery,OwnedImReply},im_inbox::{CursorSession,OnlinePosition}};
fn read(f:&mut Fixture,q:Arc<ImQuery>,bytes:&[u8])->OwnedImReply{let p=f.backend.prepare_im_read(q,f.gate.clone(),Instant::now()+Duration::from_secs(3)).unwrap();f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(p.call_id,bytes),0).unwrap();let mut r=f.backend.take_im_replies();assert_eq!(r.len(),1);r.pop().unwrap()}
fn start(f:&mut Fixture,target:i64)->CursorSession{
    let mut w=Writer::new();w.boolean(true).unwrap();w.u32(1).unwrap();w.bytes(b"0_1").unwrap();let target=target.to_string();w.properties(&[RpcProperty{key:n::im_status::PEER_READ,value:b"0"},RpcProperty{key:n::im_status::LATEST,value:target.as_bytes()}]).unwrap();w.i64(1).unwrap();w.bytes(b"").unwrap();let r=read(f,Arc::new(ImQuery::refresh(&[],-1).unwrap()),w.finish().expose_to_transport());let ctx=org(f,r.request().binding());let mut c=CursorSession::from_refresh(f.run.clone(),f.gate.clone(),&r).unwrap().with_org_context(Some(ctx)).unwrap();c.observe_refresh(&f.temp.database,&r).unwrap();c
}
fn response(raws:&[Vec<u8>])->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(raws.len()as u32).unwrap();for raw in raws{let m=n::im_data::ImMessage::decode(raw).unwrap();w.i64(m.index).unwrap();w.i64(m.time).unwrap();w.bytes(m.sender_uid).unwrap();w.bytes(m.kind).unwrap();w.bytes(m.content).unwrap();w.properties(&m.attachments).unwrap();w.properties(&m.parameters).unwrap();}w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
fn text(index:i64)->Vec<u8>{n::im_data::ImMessage{index,time:7,sender_uid:b"private-sender",kind:b"Text",content:br#"{"text":"ordinary text"}"#,attachments:vec![],parameters:vec![]}.encode().unwrap().expose_to_transport().to_vec()}
fn position(f:&Fixture)->(i64,i64,i64){f.temp.database.with_conn(|c|c.query_row("SELECT baseline,consumed,target FROM app_voice_im_receive_cursors WHERE box_id=?1",[org_relation_sync::SYSTEM_BOX],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|_|"fixture")).unwrap()}
#[test]fn org_relation_cursor_mixed_gap_commits_control_and_chat_atomically_before_consumed_position(){let mut f=fixture(true);let c=start(&mut f,3);let gap=c.next_gap(&f.temp.database).unwrap().unwrap();let r=read(&mut f,gap.query(),&response(&[raw(2,Some(0),Some(1),Some(1)),text(1),text(3)]));let done=c.commit_gap(&f.temp.database,&gap,&r).unwrap();assert_eq!(done.end(),3);assert_eq!(done.proofs().len(),3);assert_eq!(done.proofs().iter().filter(|p|p.org_receipt()).count(),1);assert_eq!(position(&f),(0,3,3));assert_eq!(count(&f),1);assert_eq!(f.count(),2);let e=event(&mut f,1,2,Some(0),Some(1),Some(1));let p=done.proofs().iter().find(|p|p.authorizes(e.ticket(),Instant::now())).unwrap();assert!(p.org_receipt());assert_eq!(result(f.backend.complete_im(e.ticket(),Some(p)).unwrap()),[0,1,0,0,0,0]);let messages=f.temp.database.with_conn(|c|n::im_inbox::list(c,f.run.line_id(),16)).unwrap();assert_eq!(messages.len(),2);assert!(messages.iter().all(|m|m.text=="ordinary text"));}
#[test]fn org_relation_cursor_malformed_or_unknown_control_rolls_back_entire_gap_not_skip_indices(){let mut f=fixture(true);let c=start(&mut f,2);let gap=c.next_gap(&f.temp.database).unwrap().unwrap();let invalid=raw(2,None,None,Some(1));let mut m=n::im_data::ImMessage::decode(&invalid).unwrap();m.parameters.retain(|p|p.key!=b"GroupId");let invalid=m.encode().unwrap().expose_to_transport().to_vec();let r=read(&mut f,gap.query(),&response(&[text(1),invalid]));assert!(c.commit_gap(&f.temp.database,&gap,&r).is_err());assert_eq!(position(&f),(0,0,2));assert_eq!(count(&f),0);assert_eq!(f.count(),0);assert!(f.temp.database.get_recent_app_events(Some(f.run.line_id()),16).unwrap().is_empty());}
#[test]fn org_relation_cursor_event_failure_rolls_back_prior_text_member_and_progress(){let mut f=fixture(true);let c=start(&mut f,2);let gap=c.next_gap(&f.temp.database).unwrap().unwrap();f.temp.database.with_conn(|c|c.execute_batch("CREATE TRIGGER fail_org BEFORE INSERT ON app_events WHEN NEW.event_type='app_voice.org_relation_observed' BEGIN SELECT RAISE(ABORT,'fixture'); END").map_err(|_|"fixture")).unwrap();let r=read(&mut f,gap.query(),&response(&[text(1),raw(2,Some(0),Some(1),Some(1))]));assert!(c.commit_gap(&f.temp.database,&gap,&r).is_err());assert_eq!(position(&f),(0,0,2));assert_eq!(count(&f),0);assert_eq!(f.count(),0);let members:i64=f.temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_org_relation_members",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(members,0);}
#[test]fn org_relation_online_gap_keeps_later_control_pending_until_original_missing_record_consumed(){let mut f=fixture(true);let c=start(&mut f,0);let e=event(&mut f,1,1,Some(0),Some(1),Some(1));assert!(matches!(c.online_position(&f.temp.database,&e).unwrap(),OnlinePosition::Next));c.commit_online(&f.temp.database,&e).unwrap().unwrap();let later=event(&mut f,2,3,Some(2),Some(3),Some(20));assert!(matches!(c.online_position(&f.temp.database,&later).unwrap(),OnlinePosition::Pending));assert!(c.commit_online(&f.temp.database,&later).is_err());assert_eq!(count(&f),1);assert_eq!(position(&f),(0,1,3));let gap=c.next_gap(&f.temp.database).unwrap().unwrap();let r=read(&mut f,gap.query(),&response(&[raw(2,Some(1),Some(2),Some(1))]));c.commit_gap(&f.temp.database,&gap,&r).unwrap();let p=c.commit_online(&f.temp.database,&later).unwrap().unwrap();assert!(p.authorizes(later.ticket(),Instant::now()));assert_eq!(position(&f),(0,3,3));let removed:i64=f.temp.database.with_conn(|c|c.query_row("SELECT removed FROM app_voice_org_relation_members",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(removed,1);}
#[test]fn org_relation_shared_message_index_cannot_change_between_chat_and_system_control(){for control_first in [false,true]{let mut f=fixture(true);let first=if control_first{event(&mut f,1,1,Some(0),Some(1),Some(1))}else{take(f.receive(1,n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes(),&args(org_relation_sync::SYSTEM_BOX,&text(1)),None))};inbox(&f,&first).commit(&f.temp.database,&first).unwrap().unwrap();let second=if control_first{take(f.receive(2,n::rpc_incoming::ONLINE_MESSAGE_METHOD.as_bytes(),&args(org_relation_sync::SYSTEM_BOX,&text(1)),None))}else{event(&mut f,2,1,Some(0),Some(1),Some(1))};assert!(inbox(&f,&second).commit(&f.temp.database,&second).is_err());assert_eq!(count(&f)+f.count(),1);}}
#[test]fn org_relation_cursor_uses_original_query_run_and_gate_not_persisted_group_timestamp(){for mode in 0..3{let mut f=fixture(true);let c=start(&mut f,1);let gap=c.next_gap(&f.temp.database).unwrap().unwrap();let r=read(&mut f,gap.query(),&response(&[raw(1,Some(i64::MIN),Some(i64::MAX),Some(1))]));match mode{0=>f.gate.retire(),1=>{f.temp.database.with_conn(|c|c.execute("DELETE FROM app_voice_runtime_leases",[]).map_err(|_|"fixture")).unwrap();},_=>{f.temp.database.with_conn(|c|c.execute("UPDATE app_voice_accounts SET private_config=X'00'",[]).map_err(|_|"fixture")).unwrap();}}assert!(c.commit_gap(&f.temp.database,&gap,&r).is_err());assert_eq!(position(&f),(0,0,1));assert_eq!(count(&f),0);}}
